const pages = $input.all().map(x => x.json);
const input = $('Normalize Input').first().json;
const requested = String(input.product_name || '').trim();

const normalize = v => String(v ?? '').toLowerCase().normalize('NFKC')
  .replace(/[يى]/g,'ی').replace(/ك/g,'ک')
  .replace(/[\\u064B-\\u065F\\u0670]/g,'')
  .replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d))
  .replace(/[^\\p{L}\\p{N}]+/gu,' ').trim();
const tokens = v => normalize(v).split(/\\s+/).filter(Boolean);
const ignored = new Set(['و','با','برای','از','در','عدد','بسته','محصول','گرم','کیلوگرم']);
const wanted = tokens(requested).filter(t=>!ignored.has(t));
const storeMap = new Map(), offerMap = new Map();
let reportedVendors=0, reportedProducts=0, validPages=0;

for (const response of pages) {
  const root = response.body ?? response;
  const data = root?.data?.vendor_product_variations;
  if (!data || !Array.isArray(data.items)) continue;
  validPages++;
  reportedVendors = Math.max(reportedVendors, Number(data.total_vendor || 0));
  reportedProducts = Math.max(reportedProducts, Number(data.total_product || 0));

  for (const store of data.items) {
    const storeId = String(store.id ?? store.vendor_id ?? '');
    const storeName = store.title ?? store.name ?? null;
    const storeKey = storeId || normalize(storeName)+'|'+normalize(store.address);
    const address = store.address ?? store.full_address ?? store.location?.address ?? null;
    const isOpen = store.is_open ?? null;
    const canDeliver = store.does_deliver ?? store.deliver ?? null;
    const category = isOpen === true
      ? (canDeliver === true ? 'باز و دارای ارسال' : 'باز و فاقد ارسال')
      : (canDeliver === true ? 'بسته و دارای اطلاعات ارسال' : 'بسته و فاقد ارسال');

    if (!storeMap.has(storeKey)) {
      storeMap.set(storeKey, {
        store_name:storeName, store_id:storeId || null,
        area:store.area ?? store.district ?? store.neighborhood ?? null,
        address, is_open:isOpen,
        store_status:isOpen === true ? 'باز' : isOpen === false ? 'بسته' : 'نامشخص',
        can_deliver:canDeliver,
        delivery_status:canDeliver === true ? 'دارد' : canDeliver === false ? 'ندارد' : 'نامشخص',
        store_category:category
      });
    }

    for (const p of (Array.isArray(store.products) ? store.products : [])) {
      const title = p.title ?? p.name ?? '';
      const price = Number(p.price);
      const discount = Number(p.discount ?? 0);
      if (!title || !Number.isFinite(price) || price <= 0 || !Number.isFinite(discount)) continue;

      const productTokens = tokens(title);
      const matched = wanted.filter(t => productTokens.some(x => x === t || x.includes(t) || t.includes(x))).length;
      const score = wanted.length ? matched / wanted.length : 0;
      const exact = normalize(title).includes(normalize(requested));
      const matchStatus = exact || score >= 0.70 ? 'مرتبط' : score >= 0.35 ? 'نیازمند بازبینی' : 'نامرتبط';
      if (matchStatus === 'نامرتبط') continue;

      const productId = String(p.id ?? p.product_id ?? p.variation_id ?? '');
      const packageSize = p.weight ?? p.volume ?? p.size ?? p.package_size ?? null;
      const dedupeKey = storeKey+'|'+(productId || normalize(title)+'|'+String(packageSize ?? ''));
      const finalPrice = price - discount;
      offerMap.set(dedupeKey, {
        store_name:storeName, store_id:storeId || null,
        area:store.area ?? store.district ?? store.neighborhood ?? null,
        address, store_status:isOpen === true ? 'باز' : isOpen === false ? 'بسته' : 'نامشخص',
        is_open:isOpen, delivery_status:canDeliver === true ? 'دارد' : canDeliver === false ? 'ندارد' : 'نامشخص',
        can_deliver:canDeliver, store_category:category,
        product_id:productId || null, product_title:title,
        brand:p.brand?.title ?? p.brand_name ?? (typeof p.brand === 'string' ? p.brand : null),
        package_size:packageSize,
        original_price:price, discount, final_price:finalPrice,
        stock:p.stock ?? p.quantity ?? null,
        stock_status:p.stock == null ? 'نامشخص' : Number(p.stock) > 0 ? 'موجود' : 'ناموجود',
        relevance:matchStatus, relevance_score:Number(score.toFixed(3)),
        received_at:new Date().toISOString()
      });
    }
  }
}

const offers=[...offerMap.values()];
const stores=[...storeMap.values()];
return [{json:{
 success:true, requested_product:requested, city:input.city || 'اصفهان',
 search_point:{latitude:Number(input.latitude),longitude:Number(input.longitude)},
 pagination:{pages_received:validPages,reported_total_vendors:reportedVendors,reported_total_products:reportedProducts},
 summary:{unique_stores:stores.length,total_relevant_offers:offers.length,
   open_with_delivery:offers.filter(x=>x.store_category==='باز و دارای ارسال').length,
   open_without_delivery:offers.filter(x=>x.store_category==='باز و فاقد ارسال').length,
   closed_with_delivery_info:offers.filter(x=>x.store_category==='بسته و دارای اطلاعات ارسال').length,
   closed_without_delivery:offers.filter(x=>x.store_category==='بسته و فاقد ارسال').length,
   needs_review:offers.filter(x=>x.relevance==='نیازمند بازبینی').length},
 stores, offers,
 note:'فروشگاه‌های بسته، فاقد ارسال و محصولات ناموجود حذف نشده‌اند. محصولات با اندازه بسته‌بندی متفاوت جدا نگه داشته می‌شوند. این نسخه فقط نقطه مرکزی اصفهان را جست‌وجو می‌کند؛ پوشش چندنقطه‌ای در مرحله بعد اضافه می‌شود.'
}}];
